MATCH (o:Owner)-[:Owns]->(t:Team)
WHERE o.name IS NOT NULL AND t.team_name IS NOT NULL
  AND EXISTS { MATCH (o)-[:MentionedIn]->(:Document) }
  AND EXISTS { MATCH (t)-[:MentionedIn]->(:Document) }
RETURN t.team_name AS col1, t.team_name AS col2, t.founded_year AS col3, o.nationality AS col4, t.team_name AS name_team, o.name AS name_manager
